const box = {
  a: 1,
  b: undefined,
  c: NaN,
  d: [undefined, 2],
  toJSON() { return { a: this.a, c: this.c, d: this.d }; },
};
const text = JSON.stringify(box);
console.log(text);
const keys = [];
const out = JSON.parse(text, (k, v) => {
  if (k) keys.push(k);
  return v === null ? 0 : v;
});
console.log(keys.join(","));
console.log(out.c, out.d[0]);
